# server.R
# Reactive logic: data load/clean/label, analysis dispatch, results rendering,
# syntax view, write-up capture, history, and report export.

#' JASP/jamovi-style variable picker: an "Available" listbox and a
#' "Selected" listbox with Add/Remove buttons moving items between them,
#' instead of a long vertical stack of checkboxes. `pool` is a named vector
#' (display label -> raw column name, from named_choices()); `picked` is
#' the vector of currently-selected raw names. Fixed widget ids ("dlb_*")
#' are safe to reuse across every technique's picker because only one is
#' ever mounted in the DOM at a time -- variable_controls fully replaces
#' its content on every category switch.
dual_listbox_ui <- function(pool, picked, label) {
  avail <- pool[!(pool %in% picked)]
  sel <- pool[pool %in% picked]
  tags$div(class = "dual-listbox",
    tags$label(label),
    tags$div(class = "dual-listbox-row",
      tags$div(class = "dual-listbox-col",
        tags$div(class = "dual-listbox-heading", "Available"),
        selectInput("dlb_avail", NULL, choices = avail, multiple = TRUE, selectize = FALSE, size = 8)
      ),
      tags$div(class = "dual-listbox-buttons",
        actionButton("dlb_add", HTML("&rarr;"), class = "btn btn-secondary dlb-btn", title = "Add to selected"),
        actionButton("dlb_remove", HTML("&larr;"), class = "btn btn-secondary dlb-btn", title = "Remove from selected")
      ),
      tags$div(class = "dual-listbox-col",
        tags$div(class = "dual-listbox-heading", "Selected"),
        selectInput("dlb_selected", NULL, choices = sel, multiple = TRUE, selectize = FALSE, size = 8)
      )
    )
  )
}

server <- function(input, output, session) {

  # -- Variable picker state (shared by every dual-listbox instance) --------
  picked_vars <- reactiveVal(character(0))
  observeEvent(input$category, picked_vars(character(0)), ignoreInit = TRUE)
  observeEvent(input$dlb_add, {
    chosen <- input$dlb_avail
    if (!is.null(chosen) && length(chosen) > 0) picked_vars(union(picked_vars(), chosen))
  })
  observeEvent(input$dlb_remove, {
    chosen <- input$dlb_selected
    if (!is.null(chosen) && length(chosen) > 0) picked_vars(setdiff(picked_vars(), chosen))
  })

  # -- Landing screen -----------------------------------------------------
  # Simple CSS text-flip animation to occupy the WASM boot wait, not a
  # marketing page: a big bold headline stack (pure CSS, no JS), Enter
  # button, app name as a small caption underneath -- same visual weight as
  # a typical CSS flip-word hero, not a small inline caption.
  # The landing overlay ("Run / <flipping word> / In your browser" behind an
  # Enter button) was removed 2026-08-25. Its stated purpose was to occupy the
  # WASM boot wait, but it could never do that: Shiny only starts once webR is
  # already up, so the overlay appeared *after* the wait it was meant to fill
  # and its only real effect was one more click before a ready app.
  #
  # The wait is now covered where it actually happens, outside Shiny, by the
  # boot splash injected into index.html by tools/postbuild_index.R. That one
  # is visible from the first paint and names the app, the 73 MB download and
  # the fact that it is one-time.
  #
  # This also removed the last use of the decorative red and green from
  # .flip-words. See the note in www/style.css.

  # -- Tab switching (bottom nav) --------------------------------------------
  observeEvent(input$nav_data, updateTabsetPanel(session, "tabs", "panel-data"))
  observeEvent(input$nav_analyse, updateTabsetPanel(session, "tabs", "panel-analyse"))
  observeEvent(input$nav_results, updateTabsetPanel(session, "tabs", "panel-results"))
  observeEvent(input$nav_learn, updateTabsetPanel(session, "tabs", "panel-learn"))

  # -- State -------------------------------------------------------------
  raw_data     <- reactiveVal(NULL)   # as loaded, cell-level edits applied, unlabelled
  metadata     <- reactiveVal(NULL)   # data.frame: Name, Type, Label, Missing, ValueLabels, Drop
  filters      <- reactiveVal(list())
  clean_log    <- reactiveVal(character(0))
  history      <- reactiveVal(list())
  last_result  <- reactiveVal(NULL)
  dataset_name <- reactiveVal("")
  active_example <- reactiveVal(NULL)  # the EXAMPLE_DATASETS entry currently loaded, or NULL

  log_action <- function(msg) {
    clean_log(c(clean_log(), sprintf("%s -- %s", format(Sys.time(), "%H:%M:%S"), msg)))
  }

  load_data <- function(df, label, seed_labels = FALSE, example = NULL) {
    raw_data(df)
    meta <- detect_types(df)
    if (seed_labels) meta <- seed_sample_labels(meta)
    # `example` is only non-NULL for a curated Demos load (see EXAMPLE_DATASETS
    # in global.R) -- same real-vs-unfamiliar-column reasoning as
    # seed_labels above, never applied to an uploaded file.
    if (!is.null(example)) meta <- apply_label_map(meta, DEMO_LABELS)
    metadata(meta)
    filters(list())
    clean_log(character(0))
    history(list())
    active_example(example)
    dataset_name(sprintf("%s (%d rows, %d columns)", label, nrow(df), ncol(df)))
    log_action(sprintf("Loaded %s.", label))
  }

  observeEvent(input$btn_load_sample, {
    df <- read.csv("data/sample_data.csv", stringsAsFactors = FALSE)
    load_data(df, "sample_data.csv (general teaching dataset)", seed_labels = TRUE)
  })

  # One Load button per curated example dataset (JASP/jamovi Data Library
  # pattern -- see EXAMPLE_DATASETS in global.R). Fixed set, known at
  # startup, so these can be wired once rather than dynamically re-bound.
  lapply(EXAMPLE_DATASETS, function(ex) {
    local({
      entry <- ex
      observeEvent(input[[paste0("load_ex_", entry$id)]], {
        df <- read.csv(file.path("data", entry$file), stringsAsFactors = FALSE)
        load_data(df, entry$title, example = entry)
      }, ignoreInit = TRUE)
    })
  })

  # The general teaching dataset (sample_data.csv) is deliberately not
  # listed in Demos -- it belongs to the actual module folder, not this
  # app, and can be added back once the app is finalised. The load
  # observer above is left in place (dead until re-wired) for that reason.

  # Show an item if at least one of its context tags is currently toggled
  # on. Every EXAMPLE_DATASETS entry is "demo" only now (self-learning
  # content is separate material, not this dataset library); this is OR
  # logic across tags, not AND, kept general for when Lecture/Tutorial
  # content exists.
  context_visible <- function(context) {
    active <- character(0)
    if (isTRUE(input$show_demo)) active <- c(active, "demo")
    if (isTRUE(input$show_lecture)) active <- c(active, "lecture")
    if (isTRUE(input$show_tutorial)) active <- c(active, "tutorial")
    if (isTRUE(input$show_selflearn)) active <- c(active, "self_learning")
    any(context %in% active)
  }

  output$data_library_box <- renderUI({
    tech_filter <- input$demo_technique

    visible <- Filter(function(ex) context_visible(ex$context), EXAMPLE_DATASETS)
    if (length(tech_filter) > 0) {
      visible <- Filter(function(ex) ex$technique == tech_filter, visible)
    }

    row_for <- function(ex, compact) {
      tags$div(class = "data-library-row",
        tags$div(class = "data-library-info",
          tags$strong(ex$title),
          if (!compact) tags$span(class = "data-library-tag",
            names(TECHNIQUE_CHOICES)[TECHNIQUE_CHOICES == ex$technique]),
          if (!compact) tags$p(class = "muted", ex$description)
        ),
        actionButton(paste0("load_ex_", ex$id), "Load", class = "btn btn-secondary")
      )
    }

    if (length(visible) == 0) {
      return(tags$div(class = "card",
        tags$h2("Demos"),
        tags$p(class = "muted", "No demos match this filter.")))
    }

    # Unfiltered, all 47 demos match. Listing them flat was measured at 5790px
    # of a 7143px page, about 8 screens of scroll on a 490px viewport, which is
    # the first thing a student sees. Titles-only cut that to 4390px, still 5
    # screens, because 47 rows is simply a lot of rows.
    #
    # So unfiltered is now grouped into collapsed <details> by technique: 13
    # closed summaries with counts, and the reader opens the one they want.
    # A chosen technique still renders the full cards, since that is the view
    # someone has actually asked for.
    body <- if (length(tech_filter) > 0) {
      tags$div(class = "data-library-list",
        lapply(visible, row_for, compact = FALSE))
    } else {
      groups <- lapply(TECHNIQUE_CHOICES, function(tc) {
        in_group <- Filter(function(ex) ex$technique == tc, visible)
        if (length(in_group) == 0) return(NULL)
        tags$details(class = "demo-group",
          tags$summary(
            tags$span(class = "demo-group-name",
              names(TECHNIQUE_CHOICES)[TECHNIQUE_CHOICES == tc]),
            tags$span(class = "demo-group-count", length(in_group))
          ),
          tags$div(class = "data-library-list",
            lapply(in_group, row_for, compact = TRUE))
        )
      })
      tags$div(class = "demo-groups", Filter(Negate(is.null), groups))
    }

    tags$div(class = "card",
      tags$h2("Demos"),
      tags$p(class = "muted",
        if (length(tech_filter) > 0) "Simulated business datasets, ready to load."
        else sprintf("%d simulated business datasets, grouped by technique. Open a group, or pick a technique above.",
                     length(visible))),
      body
    )
  })

  output$upload_box <- renderUI({
    req(isTRUE(input$show_upload))
    tags$div(class = "card",
      tags$h2("Upload data"),
      fileInput("file_input", "Choose a CSV file", accept = ".csv", buttonLabel = "Browse...", placeholder = "No file selected")
    )
  })

  observeEvent(input$file_input, {
    req(input$file_input)
    df <- tryCatch(read.csv(input$file_input$datapath, stringsAsFactors = FALSE), error = function(e) NULL)
    if (is.null(df) || nrow(df) == 0) {
      showNotification("That file could not be read as a CSV with at least one data row.", type = "error")
      return(NULL)
    }
    load_data(df, input$file_input$name)
  })

  # -- Metadata grid (typing, labels, missing codes, value labels, drop) ----
  output$meta_hot <- renderRHandsontable({
    req(metadata())
    rhandsontable(metadata(), rowHeaders = NULL, stretchH = "all") |>
      hot_col("Name", readOnly = TRUE) |>
      hot_col("Type", type = "dropdown", source = c("nominal", "ordinal", "scale")) |>
      hot_col("Label", type = "text") |>
      hot_col("Missing", type = "text") |>
      hot_col("ValueLabels", type = "text") |>
      hot_col("Drop", type = "checkbox")
  })
  observeEvent(input$meta_hot, {
    metadata(hot_to_r(input$meta_hot))
  })

  # -- Working (cleaned + labelled) data, used by every analysis ------------
  working_data <- reactive({
    req(raw_data(), metadata())
    df <- apply_metadata(raw_data(), metadata())
    apply_filters(df, filters())
  })

  # Name -> Label lookup for plot titles/axes (var_label() in global.R),
  # built from the Variables grid every time it changes. Data columns are
  # never renamed to Label (see apply_metadata()'s note on why -- formula
  # strings and picker values both rely on the raw Name), so this is the
  # only place a Label actually reaches a result: passed into every
  # plot_*() call below, display only.
  display_labels <- reactive({
    req(metadata())
    m <- metadata()
    lab <- m$Label
    names(lab) <- m$Name
    lab
  })

  # Name -> declared measurement level (nominal/ordinal/scale), same
  # source as display_labels() above. Descriptives needs this to branch
  # correctly: a numeric-coded ordinal column (kept numeric by
  # apply_metadata() so Spearman/Cronbach/EFA still work on it) can't be
  # told apart from a scale column by is.numeric() alone.
  var_types <- reactive({
    req(metadata())
    m <- metadata()
    ty <- m$Type
    names(ty) <- m$Name
    ty
  })

  # -- Data preview / edit grid ----------------------------------------------
  output$data_hot <- renderRHandsontable({
    req(raw_data())
    rhandsontable(raw_data(), rowHeaders = NULL, stretchH = "all", height = 320)
  })
  observeEvent(input$data_hot, {
    edited <- hot_to_r(input$data_hot)
    if (!identical(edited, raw_data())) {
      raw_data(edited)
      log_action("Edited data cells directly in the grid.")
    }
  })

  # -- Cleaning: duplicates, filters -----------------------------------------
  observeEvent(input$btn_remove_dupes, {
    req(raw_data())
    before <- nrow(raw_data())
    raw_data(unique(raw_data()))
    removed <- before - nrow(raw_data())
    log_action(sprintf("Removed %d duplicate row(s).", removed))
  })

  observeEvent(raw_data(), {
    req(raw_data())
    updateSelectInput(session, "filter_var", choices = names(raw_data()))
  })

  observeEvent(input$btn_add_filter, {
    req(input$filter_var, input$filter_val)
    filters(c(filters(), list(list(var = input$filter_var, op = input$filter_op, val = input$filter_val))))
    log_action(sprintf("Added filter: %s %s %s", input$filter_var, input$filter_op, input$filter_val))
  })
  observeEvent(input$btn_clear_filters, {
    if (length(filters()) > 0) log_action("Cleared all filters.")
    filters(list())
  })

  output$active_filters <- renderUI({
    fl <- filters()
    if (length(fl) == 0) return(tags$p(class = "muted", "No filters active -- every analysis uses the full (cleaned) dataset."))
    tags$ul(lapply(fl, function(f) tags$li(sprintf("%s %s %s", f$var, f$op, f$val))))
  })

  output$cleaning_log <- renderUI({
    if (length(clean_log()) == 0) return(NULL)
    tags$div(style = "margin-top:12px;",
      tags$strong("Cleaning log"),
      tags$ul(lapply(rev(clean_log()), tags$li))
    )
  })

  # -- Data tab boxes, shown only once data is loaded ------------------------
  output$data_summary_box <- renderUI({
    req(raw_data())
    ex <- active_example()
    tags$div(class = "card",
      tags$h2("Loaded data"),
      tags$p(class = "muted", dataset_name()),
      if (!is.null(ex)) tagList(
        tags$p(class = "muted", tags$strong("Suggested technique: "), names(TECHNIQUE_CHOICES)[TECHNIQUE_CHOICES == ex$technique]),
        tags$div(class = "banner", style = "background:#eef3f8;border:1px solid var(--line);",
          tags$strong("Sample interpretation"),
          tags$p(class = "caption", ex$interpretation)
        )
      )
    )
  })
  output$variables_box <- renderUI({
    req(raw_data())
    tags$div(class = "card",
      tags$h2("Variables"),
      tags$p(class = "muted", "Set each column's measurement type, an optional display label, missing-value codes (comma separated), and value labels (e.g. 1=Low; 2=Medium). Ordinal columns stay numeric so Spearman correlation, reliability, and factor analysis still work on them."),
      rHandsontableOutput("meta_hot")
    )
  })
  output$cleaning_box <- renderUI({
    req(raw_data())
    tags$div(class = "card",
      tags$h2("Cleaning"),
      actionButton("btn_remove_dupes", "Remove duplicate rows", class = "btn btn-secondary"),
      tags$div(style = "margin-top:12px;",
        tags$strong("Row filter"),
        fluidRow(
          column(4, selectInput("filter_var", NULL, choices = names(raw_data()), selectize = FALSE)),
          column(3, selectInput("filter_op", NULL, choices = c("=", "!=", ">", "<", "contains"), selectize = FALSE)),
          column(3, textInput("filter_val", NULL, placeholder = "value")),
          column(2, actionButton("btn_add_filter", "Add", class = "btn btn-secondary"))
        ),
        uiOutput("active_filters"),
        actionButton("btn_clear_filters", "Clear all filters", class = "btn btn-secondary")
      ),
      uiOutput("cleaning_log")
    )
  })
  output$data_grid_box <- renderUI({
    req(raw_data())
    tags$div(class = "card",
      tags$h2("Data preview / edit"),
      rHandsontableOutput("data_hot")
    )
  })

  # -- Analyse tab: variable pickers -----------------------------------------
  # Each returns a *named* vector (display Label -> raw column Name), so
  # every picker shows the same friendly text as the Variables grid.
  scale_cols <- reactive({
    req(metadata())
    m <- metadata()
    named_choices(m$Name[m$Type == "scale" & !m$Drop], m)
  })
  numericish_cols <- reactive({
    req(metadata())
    m <- metadata()
    named_choices(m$Name[m$Type %in% c("scale", "ordinal") & !m$Drop], m)
  })
  discrete_cols <- reactive({
    req(metadata())
    m <- metadata()
    named_choices(m$Name[m$Type %in% c("nominal", "ordinal") & !m$Drop], m)
  })
  # Descriptives is the one technique that legitimately accepts every level
  # of measurement, run_descriptive()/plot_descriptive() branch internally
  # on type (frequency table for nominal/ordinal, mean/SD summary for
  # scale) -- so its picker is not restricted to numeric-like columns the
  # way distribution shape/tests/ANOVA are (those need a real quantity).
  all_cols <- reactive({
    req(metadata())
    m <- metadata()
    named_choices(m$Name[!m$Drop], m)
  })

  output$no_data_warning <- renderUI({
    if (is.null(raw_data())) tags$div(class = "banner banner-warn", "Load a dataset on the Data tab first.")
  })
  output$analysis_picker <- renderUI({
    req(raw_data())
    tags$div(class = "card",
      selectInput("category", "Technique", choices = TECHNIQUE_CHOICES, selectize = FALSE),
      uiOutput("variable_controls"),
      actionButton("btn_analyse", "Analyse", class = "btn btn-primary btn-full")
    )
  })

  output$variable_controls <- renderUI({
    req(input$category, raw_data())
    cat_ <- input$category
    nums <- numericish_cols(); scales <- scale_cols(); discs <- discrete_cols(); everything <- all_cols()
    picked <- picked_vars()
    switch(cat_,
      descriptive = tagList(
        dual_listbox_ui(everything, picked, "Variable(s) -- categorical variables get a frequency distribution, not a mean/SD")
      ),
      distribution = tagList(
        dual_listbox_ui(nums, picked, "Numeric variable(s)")
      ),
      zscore = tagList(
        selectInput("var_zscore", "Numeric variable", choices = nums, selectize = FALSE)
      ),
      onesample = tagList(
        dual_listbox_ui(nums, picked, "Numeric variable(s)"),
        numericInput("var_mu", "Test value (comparison benchmark)", value = NA),
        selectInput("var_test", "Test", choices = c("One-sample t-test" = "ttest", "Wilcoxon signed-rank test" = "wilcoxon"), selectize = FALSE)
      ),
      twosample = tagList(
        dual_listbox_ui(nums, picked, "Numeric variable(s)"),
        selectInput("var_group", "Grouping variable (exactly two groups)", choices = discs, selectize = FALSE),
        selectInput("var_test", "Test family", choices = c("t-test" = "ttest", "Wilcoxon / Mann-Whitney (non-parametric)" = "mannwhitney"), selectize = FALSE),
        checkboxInput("var_paired", "Paired (same subjects measured twice, matched row order)", value = FALSE)
      ),
      oneway = , kruskal = tagList(
        dual_listbox_ui(nums, picked, "Numeric variable(s)"),
        selectInput("var_group", "Grouping variable (three or more groups)", choices = discs, selectize = FALSE)
      ),
      correlation = tagList(
        selectInput("var_x", "Variable 1", choices = nums, selectize = FALSE),
        selectInput("var_y", "Variable 2", choices = nums, selectize = FALSE),
        selectInput("var_method", "Method", choices = c("Pearson (scale data)" = "pearson", "Spearman (ordinal data)" = "spearman"), selectize = FALSE)
      ),
      cormatrix = tagList(
        dual_listbox_ui(nums, picked, "Variables (pick three or more)"),
        selectInput("var_method", "Method", choices = c("Pearson (scale data)" = "pearson", "Spearman (ordinal data)" = "spearman"), selectize = FALSE)
      ),
      chisquare = tagList(
        selectInput("var_cat1", "Categorical variable", choices = discs, selectize = FALSE),
        selectInput("var_type", "Test type", choices = c("Goodness of fit (one variable)" = "goodness", "Test of association (two variables)" = "association", "Fisher's exact test (two variables, small samples)" = "fisher"), selectize = FALSE),
        selectInput("var_cat2", "Second categorical variable (association / Fisher's only)", choices = c("", discs), selectize = FALSE)
      ),
      regression = tagList(
        selectInput("var_y", "Outcome (Y)", choices = scales, selectize = FALSE),
        selectInput("var_x", "Predictor (X)", choices = scales, selectize = FALSE)
      ),
      reliability = tagList(
        dual_listbox_ui(nums, picked, "Items (pick 3 or more)")
      ),
      factoranalysis = tagList(
        dual_listbox_ui(nums, picked, "Items (pick several related items)"),
        numericInput("var_factors", "Number of factors", value = 2, min = 1, max = 5),
        selectInput("var_rotation", "Rotation", choices = c("varimax", "promax", "none"), selectize = FALSE)
      )
    )
  })

  # Suggest a sensible default for the one-sample benchmark from the first
  # picked variable, once at least one is selected.
  observeEvent(picked_vars(), {
    if (identical(input$category, "onesample") && length(picked_vars()) > 0) {
      df <- working_data()
      first_var <- picked_vars()[1]
      if (first_var %in% names(df)) {
        updateNumericInput(session, "var_mu", value = round(mean(df[[first_var]], na.rm = TRUE), 1))
      }
    }
  })

  # -- Run analysis ------------------------------------------------------
  # descriptive/distribution/onesample/twosample/oneway/kruskal accept one or
  # more numeric variables and run the same technique on each, combined into
  # one table via combine_batch() -- the JASP/jamovi Descriptives/T-Tests
  # pattern of dropping several variables in at once, rather than one run per
  # variable. The other categories have genuinely distinct variable roles
  # (X vs Y, predictor sets) where "more than one" changes what's being
  # computed, so they keep their existing single-role pickers.
  batch_categories <- c("descriptive", "distribution", "onesample", "twosample", "oneway", "kruskal")

  observeEvent(input$btn_analyse, {
    df <- working_data()
    cat_ <- input$category
    vars <- picked_vars()

    is_single <- length(vars) == 1
    result <- tryCatch({
      if (cat_ %in% batch_categories) {
        if (length(vars) == 0) stop("Pick at least one numeric variable.")
        single_results <- lapply(vars, function(v) {
          switch(cat_,
            descriptive  = run_descriptive(df, v, var_types()[v], is_single),
            distribution = run_distribution(df, v),
            onesample    = run_onesample(df, v, input$var_mu, input$var_test),
            twosample    = run_twosample(df, v, input$var_group, input$var_test, isTRUE(input$var_paired)),
            oneway       = run_oneway(df, v, input$var_group),
            kruskal      = run_kruskal(df, v, input$var_group)
          )
        })
        combine_batch(vars, single_results)
      } else {
        switch(cat_,
          zscore          = run_zscore(df, input$var_zscore),
          correlation     = run_correlation(df, input$var_x, input$var_y, input$var_method),
          cormatrix       = run_correlation_matrix(df, req(picked_vars()), input$var_method),
          chisquare       = run_chisquare(df, input$var_cat1, input$var_type, input$var_cat2),
          regression      = run_regression(df, input$var_y, input$var_x),
          reliability     = run_reliability(df, req(picked_vars())),
          factoranalysis  = run_factoranalysis(df, req(picked_vars()), input$var_factors, input$var_rotation)
        )
      }
    }, error = function(e) {
      list(error = conditionMessage(e))
    })

    if (!is.null(result$error)) {
      showNotification(paste("The analysis could not run:", result$error), type = "error", duration = 8)
      return(NULL)
    }

    lbl <- display_labels()
    plot_fn <- if (cat_ %in% batch_categories) {
      single_plot_fn <- switch(cat_,
        descriptive  = function(v) plot_descriptive(df, v, lbl, var_types()[v], is_single),
        distribution = function(v) plot_distribution(df, v, lbl),
        onesample    = function(v) plot_onesample(df, v, input$var_mu, lbl),
        twosample    = function(v) plot_twosample(df, v, input$var_group, lbl),
        oneway       = function(v) plot_oneway(df, v, input$var_group, lbl),
        kruskal      = function(v) plot_kruskal(df, v, input$var_group, lbl)
      )
      function() plot_batch(vars, single_plot_fn)
    } else {
      switch(cat_,
        zscore = function() plot_zscore(df, input$var_zscore, lbl),
        correlation = function() plot_correlation(df, input$var_x, input$var_y, lbl),
        cormatrix = function() plot_correlation_matrix(df, picked_vars(), input$var_method, lbl),
        chisquare = function() plot_chisquare(df, input$var_cat1, input$var_type, input$var_cat2, lbl),
        regression = function() plot_regression(df, input$var_y, input$var_x, lbl),
        reliability = function() plot_reliability(df, picked_vars(), lbl),
        factoranalysis = function() plot_factoranalysis(df, picked_vars(), input$var_factors, input$var_rotation, lbl)
      )
    }

    label <- names(TECHNIQUE_CHOICES)[TECHNIQUE_CHOICES == cat_]
    entry <- list(id = length(history()) + 1, timestamp = Sys.time(), category = cat_, label = label,
                   result = result, plot_fn = plot_fn, writeup = "")
    last_result(entry)
    history(c(history(), list(entry)))
    updateTextAreaInput(session, "writeup", value = "")
    updateTabsetPanel(session, "tabs", "panel-results")
  })

  # -- Results rendering -------------------------------------------------
  render_result_card <- function(entry) {
    res <- entry$result
    tagList(
      tags$div(class = "card",
        tags$h2(entry$label),
        renderTable_html(res$main),
        if (!is.null(res$assumptions)) tagList(tags$h3("Assumption checks"), renderTable_html(res$assumptions)),
        if (!is.null(res$effect_size)) tagList(tags$h3("Effect size"), renderTable_html(res$effect_size)),
        if (!is.null(res$note)) tags$p(class = "caption", res$note),
        tags$img(src = plot_to_datauri(entry$plot_fn), style = "width:100%;border-radius:8px;border:1px solid var(--line);margin-top:10px;"),
        tags$details(style = "margin-top:12px;",
          tags$summary("View R code"),
          tags$pre(res$code)
        )
      )
    )
  }

  output$results_body <- renderUI({
    e <- last_result()
    if (is.null(e)) return(tags$div(class = "empty-state", tags$p("Run an analysis to see results here.")))
    render_result_card(e)
  })

  output$writeup_block <- renderUI({
    e <- last_result()
    req(e)
    draft <- build_report_paragraph(e$category, e$result)
    tags$div(class = "card",
      tags$h2("Your write-up"),
      if (!is.null(draft)) tagList(
        tags$p(class = "muted", "Suggested starting point, built from this result's actual numbers -- edit it into your own words, don't submit it as-is:"),
        tags$p(class = "report-draft", draft)
      ),
      tags$p(class = "muted", "In your own words, what does this result mean for the decision at hand?"),
      textAreaInput("writeup", NULL, rows = 4, width = "100%", placeholder = "Write a short interpretation here...")
    )
  })
  observeEvent(input$writeup, {
    e <- last_result()
    req(e)
    e$writeup <- input$writeup
    last_result(e)
    h <- history()
    if (length(h) > 0) { h[[length(h)]]$writeup <- input$writeup; history(h) }
  })

  # -- Interpretation question --------------------------------------------
  output$interpretation_block <- renderUI({
    e <- last_result()
    req(e)
    q <- INTERPRETATION_QUESTIONS[[e$category]]
    if (is.null(q)) return(NULL)
    tags$div(class = "card",
      tags$h2("Check your understanding"),
      tags$p(q$question),
      tags$div(class = "option-list",
        lapply(seq_along(q$options), function(i) {
          actionButton(paste0("opt_", i), q$options[i], class = "option-btn")
        })
      ),
      uiOutput("interpretation_feedback")
    )
  })
  lapply(1:4, function(i) {
    observeEvent(input[[paste0("opt_", i)]], {
      e <- last_result(); req(e)
      q <- INTERPRETATION_QUESTIONS[[e$category]]; req(q)
      output$interpretation_feedback <<- renderUI({
        correct <- i == q$correct
        tags$div(class = paste("feedback", if (correct) "correct" else "incorrect"),
                 if (correct) q$correct_feedback else q$incorrect_feedback)
      })
    }, ignoreInit = TRUE)
  })

  # -- History -------------------------------------------------------------
  output$history_block <- renderUI({
    h <- history()
    if (length(h) == 0) return(NULL)
    tags$div(class = "card",
      tags$h2("This session's history"),
      tags$div(class = "option-list",
        lapply(rev(h), function(entry) {
          actionButton(paste0("hist_", entry$id), sprintf("%s -- %s", entry$label, format(entry$timestamp, "%H:%M:%S")), class = "option-btn")
        })
      )
    )
  })
  observe({
    h <- history()
    lapply(h, function(entry) {
      local({
        e <- entry
        observeEvent(input[[paste0("hist_", e$id)]], { last_result(e) }, ignoreInit = TRUE)
      })
    })
  })

  # -- Report export ---------------------------------------------------------
  # HTML is the primary export: real table formatting (matches on-screen
  # exactly, via table_to_html()) plus the plot embedded as an image --
  # opens standalone, and is printable to PDF via the browser's own print
  # dialog. Plain text stays available as a secondary option (e.g. pasting
  # into a text-only field) but cannot carry table structure or a plot.
  output$btn_report_html <- downloadHandler(
    filename = function() sprintf("pocketstat-%s-report-%s.html", last_result()$category, Sys.Date()),
    content = function(file) {
      writeLines(build_report_html(last_result(), dataset_name()), file)
    }
  )
  output$btn_report_text <- downloadHandler(
    filename = function() sprintf("pocketstat-%s-summary-%s.txt", last_result()$category, Sys.Date()),
    content = function(file) {
      e <- last_result()
      lines <- c(
        paste(APP_NAME, "-- plain summary"),
        paste("Generated:", format(Sys.time())),
        paste("Dataset:", dataset_name()),
        paste("Technique:", e$label),
        "",
        capture.output(print(e$result$main, row.names = FALSE))
      )
      if (!is.null(e$result$assumptions)) lines <- c(lines, "", "Assumption checks:", capture.output(print(e$result$assumptions, row.names = FALSE)))
      if (!is.null(e$result$effect_size)) lines <- c(lines, "", "Effect size:", capture.output(print(e$result$effect_size, row.names = FALSE)))
      if (!is.null(e$result$note)) lines <- c(lines, "", e$result$note)
      if (nzchar(e$writeup %||% "")) lines <- c(lines, "", "Write-up:", e$writeup)
      lines <- c(lines, "", "R code:", e$result$code, "",
                 "This is a plain-text summary, it does not carry table formatting or the plot; use the HTML report for that.")
      writeLines(lines, file)
    }
  )
  output$report_block <- renderUI({
    req(last_result())
    tagList(
      downloadButton("btn_report_html", "Download report (HTML, formatted)", class = "btn btn-primary btn-full"),
      downloadButton("btn_report_text", "Download plain text summary", class = "btn btn-secondary btn-full")
    )
  })

  # -- Learn tab -------------------------------------------------------------
  output$learn_body <- renderUI({
    tags$div(class = "card-list",
      lapply(LEARN_CONTENT, function(item) {
        tags$div(class = "card",
          tags$h2(item$title),
          tags$p(class = "learn-summary", item$summary),
          if (!is.null(item$points)) tags$ul(class = "learn-points", lapply(item$points, tags$li)),
          if (!is.null(item$caution)) tags$p(class = "learn-caution", HTML("&#9888;&nbsp;"), item$caution)
        )
      })
    )
  })
}

/* css/style.css */

:root {
  --ink: #063970;
  --ink-soft: #4a5570;
  --paper: #f6f5f1;
  --paper-raised: #ffffff;
  --line: #dedad0;
  --accent: #063970;
  --accent-ink: #ffffff;
  --good: #2f6d4f;
  --bad: #a3402c;
  --radius: 10px;
  --nav-height: 64px;
  --topbar-height: 56px;
  --max-width: 640px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}

button, select, input {
  font-family: inherit;
}

#app {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

/* Top bar */
.topbar {
  height: var(--topbar-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  background: var(--ink);
  color: #ffffff;
  font-family: Arial, Helvetica, sans-serif;
  position: sticky;
  top: 0;
  z-index: 10;
}
.topbar-title { display: flex; flex-direction: column; line-height: 1.1; }
/* Monospace brand mark, deliberately distinct from the assistant-style
   rounded sans used everywhere else -- no CDN font load (this app has to
   work fully offline/embedded), so this tries a real "Roboto Mono" only
   where the OS already has it, falling back to other common local
   monospace fonts everywhere else. */
.topbar-title .brand-mark {
  font-family: "Roboto Mono", "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  font-weight: 700; font-size: 15px; letter-spacing: 0.01em; color: #ffffff;
}
.topbar-title .subtitle { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #ffffff; opacity: 0.8; }
.engine-status {
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(255,255,255,0.12);
  color: #e7e9f2;
}
.engine-status.ready { background: rgba(60,160,110,0.25); color: #b7f0cf; }
.engine-status.error { background: rgba(200,70,50,0.3); color: #ffd9cf; }

/* Panels */
main#panels {
  flex: 1;
  padding: 16px 16px calc(var(--nav-height) + 24px);
  max-width: var(--max-width);
  margin: 0 auto;
  width: 100%;
}
.panel { display: none; }
.panel.active { display: block; animation: fade-in 0.15s ease-out; }
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }

h1 { font-size: 22px; margin: 4px 0 4px; }
h2 { font-size: 16px; margin: 0 0 8px; }
.lede { color: var(--ink-soft); font-size: 14px; margin: 0 0 20px; }
.muted { color: var(--ink-soft); font-size: 13px; }

/* Cards */
.card {
  background: var(--paper-raised);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 14px;
}
.card-list { display: flex; flex-direction: column; gap: 10px; }

/* Buttons, minimum 44px touch target */
.btn {
  min-height: 44px;
  padding: 10px 18px;
  border-radius: 8px;
  border: none;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  touch-action: manipulation;
}
.btn-primary { background: var(--accent); color: var(--accent-ink); }
.btn-primary:active { opacity: 0.85; }
.btn-secondary { background: var(--paper); color: var(--ink); border: 1px solid var(--line); }
.btn-full { width: 100%; margin-top: 12px; }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }

/* File input */
.file-drop {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 56px;
  border: 2px dashed var(--line);
  border-radius: var(--radius);
  color: var(--ink-soft);
  font-size: 14px;
  cursor: pointer;
}
.file-drop:active { background: var(--paper); }

/* Form controls, full width, thumb-friendly */
label { display: block; font-size: 13px; font-weight: 600; margin: 12px 0 6px; color: var(--ink-soft); }
select, input[type="number"], input[type="text"] {
  width: 100%;
  min-height: 44px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 15px;
  background: #fff;
  color: var(--ink);
}

/* Banners */
.banner {
  padding: 12px 14px;
  border-radius: var(--radius);
  font-size: 14px;
  margin-bottom: 14px;
}
.banner-warn { background: #fbeee0; color: #7a4a15; border: 1px solid #edd3ae; }
.banner-error { background: #fbe4e0; color: var(--bad); border: 1px solid #f0bdb4; }

/* Results */
.empty-state { color: var(--ink-soft); font-size: 14px; padding: 24px 0; text-align: center; }
.result-table-wrap { overflow-x: auto; -webkit-overflow-scrolling: touch; margin: 10px 0; }

/* APA-style table: rule above the header, a thin rule under the header row,
   a rule below the last row, no vertical lines, no per-row rules. Numeric
   columns (tagged with class="num" by table_to_html()) are right-aligned,
   the standard convention for reading a column of numbers. */
table.result-table {
  border-collapse: collapse; width: 100%; font-size: 14px;
  border-top: 2px solid var(--ink); border-bottom: 2px solid var(--ink);
}
table.result-table th, table.result-table td {
  padding: 8px 10px;
  text-align: left;
  white-space: nowrap;
}
table.result-table thead tr { border-bottom: 1px solid var(--ink); }
table.result-table th { color: var(--ink); font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: 0.03em; }
table.result-table td.num, table.result-table th.num { text-align: right; font-variant-numeric: tabular-nums; }
.table-caption { font-size: 13px; font-weight: 600; color: var(--ink); margin: 14px 0 2px; }

.caption { font-size: 13px; color: var(--ink-soft); margin: 6px 0 16px; line-height: 1.45; }
canvas.plot-canvas { width: 100%; height: auto; background: #fff; border-radius: 8px; border: 1px solid var(--line); }

/* Interpretation options */
.option-list { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; }
.option-btn {
  min-height: 44px;
  text-align: left;
  padding: 10px 14px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: #fff;
  font-size: 14px;
  cursor: pointer;
}
.option-btn.correct { border-color: var(--good); background: #eaf4ee; }
.option-btn.incorrect { border-color: var(--bad); background: #fbeae7; }
.feedback { margin-top: 10px; font-size: 14px; padding: 10px; border-radius: 8px; }
.feedback.correct { background: #eaf4ee; color: var(--good); }
.feedback.incorrect { background: #fbeae7; color: var(--bad); }

/* Bottom nav, mobile-first */
.bottomnav {
  position: fixed;
  left: 0; right: 0; bottom: 0;
  height: var(--nav-height);
  display: flex;
  background: var(--paper-raised);
  border-top: 1px solid var(--line);
  padding-bottom: env(safe-area-inset-bottom);
  z-index: 20;
}
.navbtn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  border: none;
  background: none;
  color: var(--ink-soft);
  font-size: 11px;
  min-height: 44px;
  cursor: pointer;
}
.navbtn .navicon { font-size: 20px; line-height: 1; display: flex; }
.navbtn .navicon svg { display: block; width: 20px; height: 20px; }
.navbtn.active { color: var(--accent); font-weight: 700; }
.navbtn.active .navicon svg { stroke-width: 2.4; }

/* Loading overlay */
.loading-overlay {
  position: fixed; inset: 0;
  background: var(--ink);
  color: #fff;
  display: flex; align-items: center; justify-content: center;
  z-index: 100;
  transition: opacity 0.25s ease;
}
.loading-overlay.hidden { opacity: 0; pointer-events: none; }
.loading-box { text-align: center; max-width: 280px; padding: 0 20px; }
.spinner {
  width: 36px; height: 36px;
  border: 3px solid rgba(255,255,255,0.25);
  border-top-color: var(--accent);
  border-radius: 50%;
  margin: 0 auto 16px;
  animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
.loading-sub { font-size: 12px; color: #b9c0d6; margin-top: 8px; }

/* Desktop: widen, move nav to top */
@media (min-width: 768px) {
  :root { --max-width: 760px; }
  .bottomnav {
    position: sticky;
    top: var(--topbar-height);
    height: 52px;
    justify-content: center;
    gap: 32px;
  }
  .navbtn { flex: none; flex-direction: row; gap: 6px; font-size: 13px; padding: 0 4px; }
  .navbtn .navicon { font-size: 16px; }
  .navbtn .navicon svg { width: 17px; height: 17px; }
  main#panels { padding-bottom: 40px; }
}

