/* ---------------------------------------------------------------------- */

/* Shiny's tabsetPanel(type = "hidden") relies on .tab-pane/.active for
   show/hide. Defined explicitly here so panel switching works correctly
   even if Bootstrap's own CSS isn't loaded (this app deliberately doesn't
   use fluidPage/bootstrapPage, to keep the original minimal look). */
.tab-content > .tab-pane { display: none; }
.tab-content > .tab-pane.active { display: block; animation: fade-in 0.15s ease-out; }

/* rhandsontable containers */
.handsontable { font-size: 13px; }
#meta_hot, #data_hot { margin-top: 8px; overflow-x: auto; }

/* Syntax view */
details > summary { cursor: pointer; font-size: 13px; font-weight: 600; color: var(--ink-soft); }
details pre {
  background: #17233d; color: #e7e9f2; padding: 12px; border-radius: 8px;
  font-size: 12px; overflow-x: auto; margin-top: 8px; white-space: pre-wrap;
}

/* Assumption / effect-size sub-tables */
.card h3 { font-size: 13px; margin: 14px 0 4px; color: var(--ink-soft); text-transform: uppercase; letter-spacing: 0.03em; }

/* Learn tab: structured entries (summary + bullets + optional caution),
   not one flat paragraph. */
.learn-summary { font-weight: 600; font-size: 14px; margin: 0 0 8px; }
.learn-points { margin: 0 0 4px; padding-left: 20px; }
.learn-points li { margin-bottom: 5px; font-size: 13px; color: var(--ink-soft); line-height: 1.45; }
.learn-caution {
  display: flex; align-items: flex-start; gap: 4px;
  font-size: 13px; color: var(--bad); background: #fbeae7;
  border-radius: 6px; padding: 8px 10px; margin: 10px 0 0; line-height: 1.4;
}

/* Report paragraph builder: a real draft, styled distinctly from both the
   result table and the student's own write-up, so it never reads as "the
   answer" to just copy. */
.report-draft {
  font-style: italic; font-size: 13px; color: var(--ink);
  background: #eef3f8; border-radius: 6px; padding: 10px 12px; margin: 6px 0 12px; line-height: 1.5;
}

/* Dual-listbox variable picker (Available <-> Selected, JASP/jamovi style),
   replaces the old vertical checkbox stack. */
.dual-listbox { margin-top: 4px; }
.dual-listbox-row {
  display: flex; align-items: stretch; gap: 8px; margin-top: 6px;
}
.dual-listbox-col { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.dual-listbox-heading {
  font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.03em;
  color: var(--ink-soft); margin-bottom: 4px;
}
.dual-listbox-col select[multiple] {
  flex: 1; min-height: 168px; border: 1px solid var(--line); border-radius: 6px;
  font-size: 13px; padding: 4px;
}
.dual-listbox-col select[multiple] option { padding: 4px 6px; border-radius: 3px; }
.dual-listbox-buttons {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px;
}
.dlb-btn {
  min-height: 36px; width: 44px; padding: 0; font-size: 16px; line-height: 1;
}

/* Checkbox groups (still used elsewhere for plain option lists) */
.shiny-options-group { display: flex; flex-direction: column; gap: 6px; margin-top: 6px; }

/* Cleaning log */
#cleaning_log ul, .cleaning-log ul { padding-left: 18px; font-size: 12px; color: var(--ink-soft); }

/* Neutralise Shiny/Bootstrap default control spacing so ported .card/.btn
   rules stay in charge of layout. */
.form-group { margin-bottom: 0; }
.shiny-input-container { width: 100%; max-width: none; }

/* Example dataset library (Data tab, JASP/jamovi Data Library pattern) */
.data-library-list { display: flex; flex-direction: column; gap: 0; }
.data-library-row {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 12px 0; border-bottom: 1px solid var(--line);
}
.data-library-row:last-child { border-bottom: none; }
.data-library-info { flex: 1; min-width: 0; }
.data-library-info strong { font-size: 14px; }
.data-library-info p { margin: 4px 0 0; font-size: 12px; }
.data-library-tag {
  display: inline-block; margin-left: 8px; padding: 1px 8px; border-radius: 999px;
  background: #eef3f8; color: var(--ink); font-size: 10px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.03em; vertical-align: middle;
}
.data-library-row .btn { flex-shrink: 0; min-width: 72px; }

/* Data tab show/hide filter toggles. Bootstrap's own .checkbox CSS
   (loaded via fluidPage) positions the <input> with position:absolute and
   a negative margin-left, relying on the <label> having left padding to
   make room -- styling the wrapper div with flex/gap (as a first pass
   here did) does nothing, input and text are nested inside the <label>,
   not direct children of the div being flexed. Fixed by neutralising the
   absolute positioning and making the <label> itself the flex container. */
.filter-toggle-row {
  display: flex; flex-wrap: wrap; gap: 6px 16px; margin-top: 4px;
}
.filter-toggle-row .form-group { margin-bottom: 0; }
.filter-toggle-row .checkbox { margin: 0; min-height: 32px; }
.filter-toggle-row .checkbox label {
  display: flex; align-items: center; gap: 6px;
  padding-left: 0; margin: 0; font-weight: 400; color: var(--ink); font-size: 13px; min-height: 32px;
}
.filter-toggle-row input[type="checkbox"] {
  position: static; width: 16px; height: 16px; margin: 0; flex-shrink: 0;
}

/* Show + Technique side by side. Deliberately a plain flex row, not
   Bootstrap's column()/col-sm-* grid -- those only split into columns
   from the sm breakpoint (768px) up, so on an actual phone viewport
   (this app is mobile-first) they'd silently collapse back to one
   column, the opposite of what was asked for. flex keeps two columns
   wherever two columns actually fit.

   Rewritten 2026-08-25 after the layout was found broken in a ~490px
   iframe, which is how this embeds in Moodle: Show was crushed to about
   144px and "Self-learning" and "Upload data" each broke onto 2 lines.

   The cause was a selector that never matched what it looked like it
   matched. conditionalPanel() wraps the Technique card in its own div,
   so the real DOM is:

       .two-col-row
         |- div.card                     <- Show
         '- div.shiny-panel-conditional  <- wrapper
              '- div.card                <- Technique

   `.two-col-row > .card` therefore selected Show ALONE. Show took
   `flex: 1 1 0` (zero basis, grow), the wrapper was left at its default
   `flex: 0 1 auto` and so held its ~334px content width, and whatever
   remained went to Show. Wide viewport: Show ballooned. Narrow viewport:
   Show starved. Both were the same bug.

   Selectors below are structural, not class-based, so they keep working
   if Shiny renames its conditionalPanel wrapper. */
.two-col-row {
  display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-start;
}
.two-col-row > * { min-width: 0; }
/* Show: a fixed narrow column. NOT `flex: 0 0 auto`, which was tried and
   is wrong here: `.card` is a plain block, so an auto basis resolves to
   max-content, and this card's max-content is all 5 checkboxes on a
   single line, about 1600px. 200px leaves 168px of content after the
   card's 16px padding, enough for "Self-learning" on one line, and the
   checkbox row wraps to one per line, which is the intended shape. A
   50/50 split was never right, the 2 cards hold very different amounts. */
.two-col-row > :first-child { flex: 0 0 200px; }
/* Technique: takes the remaining width, and is allowed to wrap onto its
   own full-width row when what remains would be too narrow to use. */
.two-col-row > :nth-child(2) { flex: 1 1 260px; }
/* The card inside the conditionalPanel wrapper must fill it, otherwise
   the wrapper grows and the card does not. */
.two-col-row > :nth-child(2) > .card { width: 100%; }

/* Below this, neither card can hold its content beside the other. */
@media (max-width: 559px) {
  .two-col-row { flex-direction: column; }
  .two-col-row > :first-child,
  .two-col-row > :nth-child(2) { flex: 1 1 auto; width: 100%; min-width: 0; }
}

/* The landing screen (.landing-overlay, .landing-box, .hero-line,
   .flip-words, .landing-caption and @keyframes flip-cycle) was deleted
   2026-08-25 along with the Enter gate it belonged to. See the note in
   server.R: it was built to occupy the WASM boot wait but rendered only
   after that wait was already over, so it just added a click to a ready app.
   The boot splash in tools/postbuild_index.R covers the real wait.

   COLOUR RULE, worth keeping even though the markup is gone. .flip-words
   coloured its 5 words with var(--accent), var(--good), var(--ink-soft),
   var(--bad) and a one-off #6a4c93. Two problems, and both apply to anything
   added later:

   1. --good (green) and --bad (red) carry meaning in a statistics app:
      assumption met or violated, significant or not, a check that passed or
      failed. Spending them on decoration teaches the reader that the colours
      mean nothing, and then they cannot be trusted where they do. Reserve
      them for state, never for ornament.
   2. #6a4c93 was a literal not present in :root, so it sat outside the
      palette and outside any contrast checking done on it.

   Decorative fills should use --accent, --ink-soft or --line. */



/* Unfiltered demo library: 13 collapsed groups, one per technique, instead of
   47 flat rows. Native <details>/<summary>, so it needs no JavaScript, is
   keyboard operable and is announced correctly by screen readers without any
   aria- attributes of our own. */
.demo-groups { display: flex; flex-direction: column; gap: 2px; }
.demo-group { border-top: 1px solid var(--line); }
.demo-group:last-child { border-bottom: 1px solid var(--line); }
.demo-group > summary {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 12px 4px; cursor: pointer; list-style: none;
  font-weight: 600; color: var(--ink); min-height: 44px;
}
.demo-group > summary::-webkit-details-marker { display: none; }
/* Disclosure triangle drawn rather than using the native marker, which cannot
   be positioned consistently across browsers. */
.demo-group > summary::before {
  content: ""; flex: 0 0 auto; width: 0; height: 0;
  border-left: 5px solid var(--ink-soft);
  border-top: 4px solid transparent; border-bottom: 4px solid transparent;
  margin-right: 8px; transition: transform .15s ease;
}
.demo-group[open] > summary::before { transform: rotate(90deg); }
.demo-group > summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.demo-group-name { flex: 1 1 auto; }
.demo-group-count {
  flex: 0 0 auto; font-weight: 400; font-size: 12px; color: var(--ink-soft);
  background: var(--paper); border: 1px solid var(--line);
  border-radius: 999px; padding: 1px 8px;
}
.demo-group .data-library-list { padding: 0 0 8px 13px; }
.demo-group .data-library-row { padding-top: 8px; padding-bottom: 8px; }
@media (prefers-reduced-motion: reduce) {
  .demo-group > summary::before { transition: none; }
}
